// A new reference makes the change easy to detect.

const numbers = [1, 2, 3];

// Mutation
numbers.push(4);
console.log(numbers); // [1, 2, 3, 4]

// Immutable approach
const original = [1, 2, 3];
const updated = [...original, 4];

console.log(original); // [1, 2, 3]
console.log(updated);  // [1, 2, 3, 4]

const user = {
  name: "Jeet",
  age: 25,
  city: "Kolkata"
};

const updatedUser = {
  ...user,
  age: 26
};

console.log(user);
// { name: "Jeet", age: 25, city: "Kolkata" }

console.log(updatedUser);
// { name: "Jeet", age: 26, city: "Kolkata" }

const users = [
  { id: 1, name: "Jeet" },
  { id: 2, name: "John" }
];

// Update an item without mutating the array
const updatedUsers = users.map(user =>
  user.id === 1
    ? { ...user, name: "Alex" }
    : user
);

console.log(users);
// Original array remains unchanged

console.log(updatedUsers);
// First user's name is now "Alex"

